"""
    Determine if value is a float

    Parameters
    ----------
    value :
        Value
    """
def isfloat(value: Any) -> object {
    try {
        float_val = float(value);
        if ((float_val == value) or (str(float_val) == value)) {
            return True;
        } else {
            return False;
        }
    } except ValueError {
        return False;
    }
}

